#define _POSIX_C_SOURCE 200809L
#include "mutable_views.h"
#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"ADO_CHECK %s:%d %s\n",__FILE__,__LINE__,#x);return 1;}}while(0)
static int geometry(void){AdvGeometry g={777,888};CHECK(adv_geometry(6,2,2,2,3,&g)==ADV_OK&&g.required==6&&g.injective);CHECK(adv_geometry(3,2,2,1,1,&g)==ADV_OK&&!g.injective);CHECK(adv_geometry(5,2,2,2,2,&g)==ADV_OK&&!g.injective);g=(AdvGeometry){777,888};CHECK(adv_geometry(4,2,2,3,1,&g)==ADV_RANGE&&g.required==777&&g.injective==888);CHECK(adv_geometry(SIZE_MAX,2,1,SIZE_MAX,1,&g)==ADV_RANGE&&g.required==777);CHECK(adv_geometry(SIZE_MAX,SIZE_MAX,2,2,1,&g)==ADV_RANGE&&g.required==777);CHECK(adv_geometry(0,0,SIZE_MAX,0,0,&g)==ADV_OK&&g.required==0&&g.injective);CHECK(adv_geometry(SIZE_MAX,1,1,SIZE_MAX,SIZE_MAX,&g)==ADV_OK&&g.required==1&&g.injective);uint32_t a[8]={0};AdvView v={0};CHECK(adv_view(a,5,2,2,2,2,&v)==ADV_ALIAS&&v.data==NULL);CHECK(adv_view(a,6,2,2,2,3,&v)==ADV_OK);puts("ADV_GEOMETRY exact-gcd-injectivity");return 0;}
static int transforms(void){uint32_t a[8]={1,2,3,99,4,5,6,88};AdvView v,t,s;CHECK(adv_view(a,7,2,3,4,1,&v)==ADV_OK);CHECK(adv_transpose(v,&t)==ADV_OK);CHECK(adv_set(t,1,0,20)==ADV_OK&&a[1]==20&&a[4]==4);CHECK(adv_subview(v,1,1,1,2,&s)==ADV_OK&&s.data==a+5&&s.capacity==2);CHECK(adv_set(s,0,0,50)==ADV_OK&&a[5]==50&&a[4]==4);AdvView old=s;CHECK(adv_subview(v,2,0,1,1,&s)==ADV_RANGE&&s.data==old.data&&s.capacity==old.capacity);CHECK(adv_subview(v,2,3,0,0,&s)==ADV_OK&&s.data==a&&s.rows==0);CHECK(adv_view(NULL,0,0,7,0,0,&v)==ADV_OK);CHECK(adv_subview(v,0,7,0,0,&s)==ADV_OK&&s.data==NULL);CHECK(adv_set(s,0,0,8)==ADV_RANGE);puts("ADV_TRANSFORM transpose-submatrix-borrow");return 0;}
static int vector(void){uint32_t a[9]={4,1,2,3,4,5,6,7,8};CHECK(adv_vector4(a+1)==10);uint32_t wide[4]={UINT32_MAX,1,UINT32_MAX,2};CHECK(adv_vector4(wide)==UINT64_C(8589934593));ADView v;CHECK(ad_view(a+1,8,1,8,8,1,&v));AdvReduction out={0};CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OK&&out.sum==36&&out.vector_blocks==2&&out.scalar_elements==0);puts("ADV_VECTOR widened-four-lane-result");return 0;}
static int reduction(void){uint32_t a[8]={1,2,3,4,5,6,7,8};ADView v;AdvReduction out={777,ADV_AUTO,88,99};CHECK(ad_view(a,8,1,7,7,1,&v));CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OK&&out.sum==28&&out.vector_blocks==1&&out.scalar_elements==3);a[0]=UINT32_MAX;out=(AdvReduction){777,ADV_AUTO,88,99};CHECK(adv_reduce(v,ADV_SCALAR,&out)==ADV_OVERFLOW&&out.sum==777&&out.vector_blocks==88);CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OVERFLOW&&out.sum==777);a[0]=1;a[6]=UINT32_MAX;CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OVERFLOW&&out.sum==777&&out.backend==ADV_AUTO&&out.vector_blocks==88&&out.scalar_elements==99);a[6]=7;CHECK(ad_view(a,8,2,2,1,2,&v));CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_LAYOUT&&out.sum==777);CHECK(adv_reduce(v,ADV_AUTO,&out)==ADV_OK&&out.backend==ADV_SCALAR&&out.sum==10&&out.scalar_elements==4);CHECK(ad_view(a,3,2,2,1,1,&v));CHECK(adv_reduce(v,ADV_AUTO,&out)==ADV_OK&&out.sum==8);CHECK(ad_view(NULL,0,0,999,0,0,&v));CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OK&&out.sum==0&&out.vector_blocks==0&&out.scalar_elements==0);
 uint32_t padded[14];for(unsigned i=0;i<14;++i)padded[i]=i+1;AdvView whole,sub,t;CHECK(adv_view(padded,12,2,5,7,1,&whole)==ADV_OK);CHECK(adv_reduce(adv_readonly(whole),ADV_VECTOR,&out)==ADV_OK&&out.sum==65&&out.vector_blocks==2&&out.scalar_elements==2);CHECK(adv_subview(whole,0,1,2,3,&sub)==ADV_OK);CHECK(adv_transpose(sub,&t)==ADV_OK);CHECK(adv_reduce(adv_readonly(t),ADV_AUTO,&out)==ADV_OK&&out.sum==39&&out.backend==ADV_SCALAR);CHECK(adv_reduce(adv_readonly(t),ADV_VECTOR,&out)==ADV_LAYOUT&&out.sum==39);CHECK(adv_set(t,1,1,30)==ADV_OK&&padded[9]==30);CHECK(adv_reduce(adv_readonly(t),ADV_AUTO,&out)==ADV_OK&&out.sum==59);puts("ADV_REDUCE equal-overflow-alias-policy padded-transpose-tail");return 0;}
static int baseline(void){uint32_t a[]={1,2,99,3,4};ADView v;uint32_t x=99;CHECK(ad_view(a,5,2,2,3,1,&v));CHECK(ad_view_get(v,1,1,&x)&&x==4);ADView saved=v;CHECK(!ad_view(a,4,2,2,3,1,&v)&&v.capacity==saved.capacity);CHECK(!ad_view(a,5,SIZE_MAX,2,SIZE_MAX,1,&v));CHECK(ad_view(NULL,0,0,3,0,0,&v));CHECK(!ad_view_get(v,0,0,&x));puts("ADV_BASE actual-readonly-strides");return 0;}
static void result(ADView v,AdvMode mode){AdvReduction out={777,ADV_AUTO,88,99};AdvStatus status=adv_reduce(v,mode,&out);printf(" %u %" PRIu32 " %u %zu %zu",(unsigned)status,out.sum,(unsigned)out.backend,out.vector_blocks,out.scalar_elements);}
static int oracle(void){size_t rows,cols,rs,cs,cap;unsigned pattern;while(scanf("%zu %zu %zu %zu %zu %u",&rows,&cols,&rs,&cs,&cap,&pattern)==6){if(cap>64||rows>8||cols>8||rs>9||cs>9||pattern>2)return 2;uint32_t data[64];for(unsigned i=0;i<64;++i)data[i]=pattern==0?i+1:pattern==1?(i%5==0?UINT32_MAX:1):0;AdvGeometry g={777,888};AdvStatus gs=adv_geometry(cap,rows,cols,rs,cs,&g);ADView read={0};int admitted=ad_view(data,cap,rows,cols,rs,cs,&read);uint64_t total=0;if(admitted)for(size_t r=0;r<rows;++r)for(size_t c=0;c<cols;++c){uint32_t x;CHECK(ad_view_get(read,r,c,&x));total+=x;}AdvView view={0};AdvStatus vs=adv_view(data,cap,rows,cols,rs,cs,&view);printf("%u %zu %u %d %" PRIu64 " %u",(unsigned)gs,g.required,g.injective,admitted,total,(unsigned)vs);
 if(admitted){result(read,ADV_SCALAR);result(read,ADV_VECTOR);result(read,ADV_AUTO);}else printf(" -");
 if(vs==ADV_OK&&rows&&cols){AdvView t,sub;CHECK(adv_transpose(view,&t)==ADV_OK);CHECK(adv_set(t,cols-1,rows-1,111)==ADV_OK);size_t r=rows>1?1:0,c=cols>1?1:0;CHECK(adv_subview(view,r,c,rows-r,cols-c,&sub)==ADV_OK);CHECK(adv_set(sub,0,0,222)==ADV_OK);uint64_t checksum=0;for(size_t i=0;i<cap;++i)checksum+=(uint64_t)(i+1)*data[i];printf(" %zu %zu %zu %" PRIu64,(size_t)(sub.data-data),sub.capacity,t.row_stride,checksum);}else printf(" -");puts("");}return 0;}
static double seconds(void){struct timespec t;if(clock_gettime(CLOCK_MONOTONIC,&t))return 0;return(double)t.tv_sec+(double)t.tv_nsec/1e9;}
static int metrics(void){uint32_t data[2240];for(unsigned i=0;i<2240;++i)data[i]=1;ADView v;CHECK(ad_view(data,2240,32,64,70,1,&v));AdvReduction out;CHECK(adv_reduce(v,ADV_SCALAR,&out)==ADV_OK);CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OK);double scalar[7],vector[7];uint64_t checksum=0;for(unsigned k=0;k<7;++k){double t=seconds();checksum=0;for(unsigned i=0;i<1000;++i){CHECK(adv_reduce(v,ADV_SCALAR,&out)==ADV_OK);checksum+=out.sum;}scalar[k]=seconds()-t;t=seconds();checksum=0;for(unsigned i=0;i<1000;++i){CHECK(adv_reduce(v,ADV_VECTOR,&out)==ADV_OK);checksum+=out.sum;}vector[k]=seconds()-t;}printf("{\"iterations\":1000,\"elements\":2048,\"checksum\":%" PRIu64 ",\"view_size\":%zu,\"view_alignment\":%zu,\"scalar_seconds\":[",checksum,sizeof(AdvView),_Alignof(AdvView));for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",scalar[i]);printf("],\"vector_seconds\":[");for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",vector[i]);puts("]}");return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"view_geometry"))return geometry();if(!strcmp(argv[1],"view_transform"))return transforms();if(!strcmp(argv[1],"view_vector"))return vector();if(!strcmp(argv[1],"view_reduction"))return reduction();if(!strcmp(argv[1],"view_base"))return baseline();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}
